// The pin of a technique by name; null when it is not in the world set.
inline const TechniquePin* FindTechniquePin(const char* technique) noexcept {
    for(const auto& pin:world_techniques)if(!std::strcmp(pin.technique,technique))return &pin;
    return nullptr;}
// Whether a technique's two blobs (their SHA-256, upper-case hex) are the pinned ones.
inline bool CheckTechnique(const char* technique,const char* vs_sha256,const char* ps_sha256) noexcept {
    const auto* pin=FindTechniquePin(technique);
    return pin && !std::strcmp(pin->vs_sha256,vs_sha256) && !std::strcmp(pin->ps_sha256,ps_sha256);}
